// SPDX-License-Identifier: MIT
pragma solidity ^0.8.4;

/// @notice Optimized sorting and set operations library for memory arrays.
/// @author Solady (https://github.com/vectorized/solady/blob/main/src/utils/LibSort.sol)
library LibSort {
    /*´:°•.°+.*•´.*:˚.°*.˚•´.°:°•.°•.*•´.*:˚.°*.˚•´.°:°•.°+.*•´.*:*/
    /*                    INSERTION SORT                          */
    /*.•°:°.´+˚.*°.˚:*.´•*.+°.•°:´*.´•*.•°.•°:°.´:•˚°.*°.˚:*.´+°.•*/

    /// @notice Performs an insertion sort on an array of unsigned integers in-place.
    ///
    /// @dev This function uses low-level assembly for optimization and memory safety.
    /// The array is sorted in ascending order.
    ///
    /// Steps:
    /// 1. Load the length of the array `a` into `n`.
    /// 2. Temporarily set the length of `a` to 0 to ensure the inner loop terminates correctly.
    /// 3. Calculate the high slot (`h`) of the array for loop termination.
    /// 4. Initialize the loop with the first element of the array.
    /// 5. For each element in the array:
    ///    a. Load the current element (`k`).
    ///    b. Compare it with the previous element (`v`).
    ///    c. If the previous element is greater than the current element, shift the previous elements to the right until the correct position for `k` is found.
    ///    d. Insert `k` into its correct position.
    /// 6. Restore the original length of the array `a` after sorting.
    function insertionSort(uint256[] memory a) internal pure {
        /// @solidity memory-safe-assembly
        assembly {
            let n := mload(a)
            // Store the length of the array temporarily as 0.
            mstore(a, 0)
            let h := add(a, shl(5, n))
            if iszero(lt(n, 2)) {
                let l := add(a, 0x20)
                for {
                    let i := l
                } lt(i, h) {
                    i := add(i, 0x20)
                } {
                    let k := mload(i)
                    let v := mload(sub(i, 0x20))
                    if gt(v, k) {
                        let j := i
                        for {
                        } 1 {
                            j := sub(j, 0x20)
                        } {
                            mstore(j, v)
                            v := mload(sub(j, 0x40))
                            if iszero(gt(v, k)) {
                                break
                            }
                        }
                        mstore(j, k)
                    }
                }
            }
            // Restore the length of the array.
            mstore(a, n)
        }
    }

    /// @notice Performs an insertion sort on an array of signed integers in-place.
    function insertionSort(int256[] memory a) internal pure {
        insertionSort(_toUints(a));
        _toInts(a);
    }

    /// @notice Performs an insertion sort on an array of addresses in-place.
    function insertionSort(address[] memory a) internal pure {
        insertionSort(_toUints(a));
        _toAddresses(a);
    }

    /// @notice Performs an insertion sort on an array of bytes32 in-place.
    function insertionSort(bytes32[] memory a) internal pure {
        insertionSort(_toUints(a));
        _toBytes32s(a);
    }

    /*´:°•.°+.*•´.*:˚.°*.˚•´.°:°•.°•.*•´.*:˚.°*.˚•´.°:°•.°+.*•´.*:*/
    /*                    QUICKSORT                               */
    /*.•°:°.´+˚.*°.˚:*.´•*.+°.•°:´*.´•*.•°.•°:°.´:•˚°.*°.˚:*.´+°.•*/

    /// @notice Sorts an array of unsigned integers in ascending order using a combination of insertion sort and quicksort.
    ///
    /// The function uses inline assembly for optimized performance and memory safety.
    ///
    /// Steps:
    /// 1. Check if the array length is less than 2. If true, the array is already sorted, so exit.
    /// 2. Define helper functions:
    ///    - `swap`: Swaps two values.
    ///    - `mswap`: Swaps two memory slots.
    ///    - `sortInner`: Recursively sorts the array using a combination of insertion sort and quicksort.
    /// 3. Perform insertion sort if the array size is small (threshold fine-tuned via trial and error).
    /// 4. For larger arrays, use quicksort:
    ///    - Select a pivot using the median-of-three method.
    ///    - Partition the array around the pivot using Hoare's partition scheme.
    ///    - Recursively sort the sub-arrays.
    /// 5. Handle edge cases:
    ///    - If the array is already sorted, exit early.
    ///    - If the array is reverse-sorted, reverse it in place.
    /// 6. Restore the array length after sorting.
    ///
    /// @param a The array of unsigned integers to be sorted.
    function sort(uint256[] memory a) internal pure {
        /// @solidity memory-safe-assembly
        assembly {
            let n := mload(a)
            if lt(n, 2) {
                break
            }
            // Temporarily set the length of `a` to 0.
            mstore(a, 0)
            let h := add(a, shl(5, n))
            // `l` is the low slot, `h` is the high slot.
            let l := add(a, 0x20)

            // If the array is already sorted, exit early.
            let p := l
            for {
                let i := add(l, 0x20)
            } lt(i, h) {
                i := add(i, 0x20)
            } {
                if lt(mload(i), mload(p)) {
                    break
                }
                p := i
            }
            if eq(p, sub(h, 0x20)) {
                mstore(a, n)
                break
            }

            // If the array is reverse sorted, reverse it.
            p := l
            let q := sub(h, 0x20)
            for {
                let i := add(l, 0x20)
            } lt(i, h) {
                i := add(i, 0x20)
            } {
                if iszero(lt(mload(i), mload(p))) {
                    break
                }
                p := i
            }
            if eq(p, sub(h, 0x20)) {
                for {
                } lt(l, q) {
                    l := add(l, 0x20)
                    q := sub(q, 0x20)
                } {
                    let v := mload(l)
                    mstore(l, mload(q))
                    mstore(q, v)
                }
                mstore(a, n)
                break
            }
            // The length of `a` is temporarily 0.
            mstore(a, n)

            // Sort using quicksort.
            // prettier-ignore
            function swap(x, y) { x := mload(x) y := mload(y) mstore(x, y) mstore(y, x) }
            // prettier-ignore
            function mswap(x, y) { let v := mload(x) mstore(x, mload(y)) mstore(y, v) }

            // eslint-disable-next-line no-unused-vars
            function sortInner(l, h) {
                // If the number of elements is less than or equal to 42, use insertion sort.
                // The constant 42 is fine-tuned via trial and error.
                if lt(sub(h, l), 0x540) {
                    for {
                        let i := add(l, 0x20)
                    } lt(i, h) {
                        i := add(i, 0x20)
                    } {
                        let k := mload(i)
                        let v := mload(sub(i, 0x20))
                        if gt(v, k) {
                            let j := i
                            for {
                            } 1 {
                                j := sub(j, 0x20)
                            } {
                                mstore(j, v)
                                v := mload(sub(j, 0x40))
                                if iszero(gt(v, k)) {
                                    break
                                }
                            }
                            mstore(j, k)
                        }
                    }
                    // stop
                }

                // Median-of-three pivot selection.
                let m := add(shr(1, add(l, h)), and(add(l, h), 0x1f))
                let v := mload(l)
                let w := mload(m)
                if gt(v, w) {
                    mswap(l, m)
                    v := mload(l)
                    w := mload(m)
                }
                let x := mload(sub(h, 0x20))
                if gt(w, x) {
                    mswap(m, sub(h, 0x20))
                    x := mload(m)
                    w := mload(sub(h, 0x20))
                    if gt(v, w) {
                        mswap(l, m)
                        v := mload(l)
                        w := mload(m)
                    }
                }
                mswap(m, sub(h, 0x20))
                x := w
                // Hoare's partition scheme.
                let i := sub(l, 0x20)
                let j := h
                for {
                } 1 {
                    for {
                        i := add(i, 0x20)
                    } lt(mload(i), x) {
                        i := add(i, 0x20)
                    }
                    for {
                        j := sub(j, 0x20)
                    } lt(x, mload(j)) {
                        j := sub(j, 0x20)
                    }
                    if iszero(lt(i, j)) {
                        break
                    }
                    swap(i, j)
                }
                mswap(i, sub(h, 0x20))
                // Sort the sub-arrays.
                sortInner(l, i)
                sortInner(add(i, 0x20), h)
            }

            sortInner(l, h)
            // Restore the length of the array.
        }
    }

    /// @notice Sorts an array of signed integers in ascending order.
    function sort(int256[] memory a) internal pure {
        _flipSign(a);
        sort(_toUints(a));
        _flipSign(a);
        _toInts(a);
    }

    /// @notice Sorts an array of addresses in ascending order.
    function sort(address[] memory a) internal pure {
        sort(_toUints(a));
        _toAddresses(a);
    }

    /// @notice Sorts an array of bytes32 in ascending order.
    function sort(bytes32[] memory a) internal pure {
        sort(_toUints(a));
        _toBytes32s(a);
    }

    /*´:°•.°+.*•´.*:˚.°*.˚•´.°:°•.°•.*•´.*:˚.°*.˚•´.°:°•.°+.*•´.*:*/
    /*                    UNIQUIFY SORTED                         */
    /*.•°:°.´+˚.*°.˚:*.´•*.+°.•°:´*.´•*.•°.•°:°.´:•˚°.*°.˚:*.´+°.•*/

    /// @notice Removes duplicate elements from a sorted array in-place.
    ///
    /// @dev This function assumes that the input array `a` is already sorted.
    /// It uses low-level assembly to optimize memory operations and ensure gas efficiency.
    ///
    /// Steps:
    /// 1. Check if the length of the array `a` is greater than 1.
    /// 2. If true, initialize pointers `x` and `y` to the first and second elements of the array, respectively.
    /// 3. Calculate the end of the array.
    /// 4. Iterate through the array:
    ///    - If the current element at `x` is not equal to the next element at `y`, move `x` forward and store the unique element.
    ///    - Move `y` forward to the next element.
    ///    - If `y` reaches the end of the array, break the loop.
    /// 5. Update the length of the array to reflect the number of unique elements.
    ///
    /// @param a The sorted array of uint256 values to be uniquified.
    function uniquifySorted(uint256[] memory a) internal pure {
        /// @solidity memory-safe-assembly
        assembly {
            let n := mload(a)
            if lt(n, 2) {
                break
            }
            let x := add(a, 0x20)
            let y := add(x, 0x20)
            let e := add(x, shl(5, n))
            for {
            } 1 {
                if iszero(lt(y, e)) {
                    break
                }
            } {
                if iszero(eq(mload(x), mload(y))) {
                    x := add(x, 0x20)
                    mstore(x, mload(y))
                }
                y := add(y, 0x20)
            }
            mstore(a, shr(5, sub(x, add(a, 0x20))))
        }
    }

    /// @notice Removes duplicate elements from a sorted int256 array in-place.
    function uniquifySorted(int256[] memory a) internal pure {
        uniquifySorted(_toUints(a));
        _toInts(a);
    }

    /// @notice Removes duplicate elements from a sorted address array in-place.
    function uniquifySorted(address[] memory a) internal pure {
        uniquifySorted(_toUints(a));
        _toAddresses(a);
    }

    /// @notice Removes duplicate elements from a sorted bytes32 array in-place.
    function uniquifySorted(bytes32[] memory a) internal pure {
        uniquifySorted(_toUints(a));
        _toBytes32s(a);
    }

    /*´:°•.°+.*•´.*:˚.°*.˚•´.°:°•.°•.*•´.*:˚.°*.˚•´.°:°•.°+.*•´.*:*/
    /*                    SEARCH SORTED                           */
    /*.•°:°.´+˚.*°.˚:*.´•*.+°.•°:´*.´•*.•°.•°:°.´:•˚°.*°.˚:*.´+°.•*/

    /// @notice Searches for a specific value (`needle`) in a sorted array (`a`) and returns whether it was found and its index.
    ///
    /// @param a The sorted array of uint256 values to search within.
    /// @param needle The uint256 value to search for in the array.
    /// @return found A boolean indicating whether the value was found in the array.
    /// @return index The index of the found value in the array. If not found, this will be the position where the value could be inserted to maintain the sorted order.
    function searchSorted(uint256[] memory a, uint256 needle) internal pure returns (bool found, uint256 index) {
        return _searchSorted(a, needle, 0);
    }

    /// @notice Searches for a specific value (`needle`) in a sorted int256 array (`a`).
    function searchSorted(int256[] memory a, int256 needle) internal pure returns (bool found, uint256 index) {
        return _searchSorted(_toUints(a), uint256(needle) ^ (1 << 255), 1);
    }

    /// @notice Searches for a specific value (`needle`) in a sorted address array (`a`).
    function searchSorted(address[] memory a, address needle) internal pure returns (bool found, uint256 index) {
        return _searchSorted(_toUints(a), uint256(needle), 0);
    }

    /// @notice Searches for a specific value (`needle`) in a sorted bytes32 array (`a`).
    function searchSorted(bytes32[] memory a, bytes32 needle) internal pure returns (bool found, uint256 index) {
        return _searchSorted(_toUints(a), uint256(needle), 0);
    }

    /*´:°•.°+.*•´.*:˚.°*.˚•´.°:°•.°•.*•´.*:˚.°*.˚•´.°:°•.°+.*•´.*:*/
    /*                       IN SORTED                            */
    /*.•°:°.´+˚.*°.˚:*.´•*.+°.•°:´*.´•*.•°.•°:°.´:•˚°.*°.˚:*.´+°.•*/

    /// @notice Checks if a given value (`needle`) exists in a sorted array (`a`).
    ///
    /// @param a The sorted array of uint256 values to search within.
    /// @param needle The uint256 value to search for in the array.
    /// @return found A boolean indicating whether the value was found in the array.
    function inSorted(uint256[] memory a, uint256 needle) internal pure returns (bool found) {
        (found, ) = searchSorted(a, needle);
    }

    /// @notice Checks if a given value (`needle`) exists in a sorted int256 array (`a`).
    function inSorted(int256[] memory a, int256 needle) internal pure returns (bool found) {
        (found, ) = searchSorted(a, needle);
    }

    /// @notice Checks if a given value (`needle`) exists in a sorted address array (`a`).
    function inSorted(address[] memory a, address needle) internal pure returns (bool found) {
