    ///    - Move the start pointer forward and the end pointer backward.
    ///    - Continue until the start pointer is no longer less than the end pointer.
    /// 4. Exit the loop once the array is fully reversed.
    ///
    /// @param a The array of uint256 values to be reversed.
    function reverse(uint256[] memory a) internal pure {
        /// @solidity memory-safe-assembly
        assembly {
            let n := mload(a)
            if lt(n, 2) {
                break
            }
            let h := add(a, shl(5, n))
            for {
                let i := add(a, 0x20)
            } lt(i, h) {
                i := add(i, 0x20)
                h := sub(h, 0x20)
            } {
                let v := mload(i)
                mstore(i, mload(h))
                mstore(h, v)
            }
        }
    }

    /// @notice Reverses the order of elements in a given int256 array in-place.
    function reverse(int256[] memory a) internal pure {
        reverse(_toUints(a));
        _toInts(a);
    }

    /// @notice Reverses the order of elements in a given address array in-place.
    function reverse(address[] memory a) internal pure {
        reverse(_toUints(a));
        _toAddresses(a);
    }

    /// @notice Reverses the order of elements in a given bytes32 array in-place.
    function reverse(bytes32[] memory a) internal pure {
        reverse(_toUints(a));
        _toBytes32s(a);
    }

    /*´:°•.°+.*•´.*:˚.°*.˚•´.°:°•.°•.*•´.*:˚.°*.˚•´.°:°•.°+.*•´.*:*/
    /*                         COPY                              */
    /*.•°:°.´+˚.*°.˚:*.´•*.+°.•°:´*.´•*.•°.•°:°.´:•˚°.*°.˚:*.´+°.•*/

    /// @notice Copies an array of uint256 values in memory using low-level assembly for efficiency.
    ///
    /// @param a The input array of uint256 values to be copied.
    /// @return result A new array containing the copied values.
    function copy(uint256[] memory a) internal pure returns (uint256[] memory result) {
        /// @solidity memory-safe-assembly
        assembly {
            let m := mload(0x40)
            result := m
            let n := mload(a)
            mstore(result, n)
            let o := add(m, shl(5, add(n, 1)))
            mstore(0x40, and(add(o, 31), not(31)))
