    /*                    UNIQUIFY SORTED                         */
    /*.•°:°.´+˚.*°.˚:*.´•*.+°.•°:´*.´•*.•°.•°:°.´:•˚°.*°.˚:*.´+°.•*/

    /// @notice Removes duplicate elements from a sorted array in-place.
    ///
    /// @dev This function assumes that the input array `a` is already sorted.
    /// It uses low-level assembly to optimize memory operations and ensure gas efficiency.
    ///
    /// Steps:
    /// 1. Check if the length of the array `a` is greater than 1.
    /// 2. If true, initialize pointers `x` and `y` to the first and second elements of the array, respectively.
    /// 3. Calculate the end of the array.
    /// 4. Iterate through the array:
    ///    - If the current element at `x` is not equal to the next element at `y`, move `x` forward and store the unique element.
    ///    - Move `y` forward to the next element.
    ///    - If `y` reaches the end of the array, break the loop.
    /// 5. Update the length of the array to reflect the number of unique elements.
    ///
    /// @param a The sorted array of uint256 values to be uniquified.
    function uniquifySorted(uint256[] memory a) internal pure {
        /// @solidity memory-safe-assembly
        assembly {
            let n := mload(a)
            if lt(n, 2) {
                break
            }
            let x := add(a, 0x20)
            let y := add(x, 0x20)
            let e := add(x, shl(5, n))
            for {
            } 1 {
                if iszero(lt(y, e)) {
                    break
                }
            } {
                if iszero(eq(mload(x), mload(y))) {
                    x := add(x, 0x20)
                    mstore(x, mload(y))
                }
                y := add(y, 0x20)
            }
            mstore(a, shr(5, sub(x, add(a, 0x20))))
        }
    }

    /// @notice Removes duplicate elements from a sorted int256 array in-place.
    function uniquifySorted(int256[] memory a) internal pure {
        uniquifySorted(_toUints(a));
        _toInts(a);
    }

