    /// @notice Reverses the order of elements in a given array in-place.
    ///
    /// @dev This function uses low-level assembly to efficiently reverse the array.
    /// It checks if the array has fewer than 2 elements, in which case no reversal is needed.
    /// Otherwise, it iterates through the array, swapping elements from the start and end until the middle is reached.
    ///
    /// Steps:
    /// 1. Check if the array length is less than 2. If true, exit early as no reversal is needed.
    /// 2. Initialize pointers for the start (`a`) and end (`h`) of the array.
    /// 3. Iterate through the array:
    ///    - Swap the elements at the current start and end positions.
    ///    - Move the start pointer forward and the end pointer backward.
    ///    - Continue until the start pointer is no longer less than the end pointer.
    /// 4. Exit the loop once the array is fully reversed.
    ///
    /// @param a The array of uint256 values to be reversed.
    function reverse(uint256[] memory a) internal pure {
        /// @solidity memory-safe-assembly
        assembly {
            let n := mload(a)
            if lt(n, 2) {
                break
