            let h := add(a, shl(5, n))
            for {
                let i := add(a, 0x20)
            } lt(i, h) {
                i := add(i, 0x20)
                h := sub(h, 0x20)
            } {
                let v := mload(i)
                mstore(i, mload(h))
                mstore(h, v)
            }
        }
    }

